const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-120.32, 39.31]); // Donner Pass, California
  const startDateFeb = '2022-02-01';
  const endDateFeb = '2022-03-01';
  const startDateApr = '2022-04-01';
  const endDateApr = '2022-05-01';

  // 2. Data Acquisition
  const collection = ee.ImageCollection('IDAHO_EPSCOR/SNODAS').select('SWE');

  const collectionFeb = collection.filterDate(startDateFeb, endDateFeb);
  const collectionApr = collection.filterDate(startDateApr, endDateApr);

  // Check for empty collections
  const sizeFeb = collectionFeb.size().getInfo();
  const sizeApr = collectionApr.size().getInfo();

  if (sizeFeb === 0 || sizeApr === 0) {
    console.log(`Image count Feb 2022: ${sizeFeb}`);
    console.log(`Image count Apr 2022: ${sizeApr}`);
    console.log("Empty collection for one or both periods.");
    console.log("A"); // C1 is not the answer tag
    return;
  }

  // 3. Processing: Calculate monthly mean
  const meanFeb = collectionFeb.mean();
  const meanApr = collectionApr.mean();

  const scale = 1000; // SNODAS native resolution is ~1km

  // 4. Calculation: Extract SWE values at the point
  const sweFebDict = meanFeb.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: point,
    scale: scale,
  });

  const sweAprDict = meanApr.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: point,
    scale: scale,
  });

  const sweFeb = ee.Number(sweFebDict.get('SWE')).getInfo();
  const sweApr = ee.Number(sweAprDict.get('SWE')).getInfo();

  // 5. Validation & Final Answer
