  console.log(`SNODAS Daily Images Found (Apr 2022): ${sizeApr}`);

  if (sweFeb === null || sweApr === null) {
    console.log("Failed to extract a valid SWE value.");
    console.log(`SWE Feb Value: ${sweFeb}`);
    console.log(`SWE Apr Value: ${sweApr}`);
    console.log("C3");
    return;
  }

  // SNODAS SWE is in mm. Convert to meters for readability.
  const sweFeb_m = sweFeb / 1000;
  const sweApr_m = sweApr / 1000;

  console.log(`Mean SWE Feb 2022: ${sweFeb_m.toFixed(3)} m`);
  console.log(`Mean SWE Apr 2022: ${sweApr_m.toFixed(3)} m`);

  if (sweFeb > sweApr) {
    console.log("SWE was higher in February than in April 2022.");
    console.log("A");
  } else {
    console.log("SWE was not higher in February than in April 2022.");
    console.log("B");
  }
}

